/**
 * Однострочный текст, который едет ТОЛЬКО если не поместился и ТОЛЬКО под
 * курсором (или при фокусе с клавиатуры). Помещается — обычный текст с
 * многоточием, ноль анимации. При prefers-reduced-motion не едет вовсе.
 * @startingPoint section="Media" subtitle="Бегущая строка: едет только переполненное" viewport="360x120"
 */
export interface MarqueeProps {
  /** Текст. Строкой, а не children: компонент меряет переполнение и обязан
   *  знать, что именно поехало — произвольная разметка это ломает. */
  text: string;
  className?: string;
  style?: React.CSSProperties;
}
